/*
Converted the 128x128 HDR RGB textures from http://momentsingraphics.de/?p=127
using this:


#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <fstream>
#include <string>
#include <vector>
#include "pbrt-v4/src/ext/lodepng/lodepng.cpp"
#include "pbrt-v4/src/ext/lodepng/lodepng.h"

std::string ReadFileContents(const std::string &filename) {
    std::ifstream ifs(filename, std::ios::binary);
    if (!ifs) {
        fprintf(stderr, "%s: %s", filename.c_str(), strerror(errno));
        exit(1);
    }
    return std::string((std::istreambuf_iterator<char>(ifs)),
                       (std::istreambuf_iterator<char>()));
}


std::vector<uint16_t> ReadPNG(const char *name, int *xres, int *yres) {
    std::string contents = ReadFileContents(name);

    unsigned width, height;
    LodePNGState state;
    lodepng_state_init(&state);
    unsigned int error = lodepng_inspect(&width, &height, &state,
                                         (const unsigned char *)contents.data(),
                                         contents.size());
    if (error != 0) {
        fprintf(stderr, "%s: %s", name, lodepng_error_text(error));
        exit(1);
    }

    *xres = width;
    *yres = height;

    assert(state.info_png.color.colortype != LCT_GREY &&
           state.info_png.color.colortype != LCT_GREY_ALPHA);

    int bpp = state.info_png.color.bitdepth == 16 ? 16 : 8;
    std::vector<unsigned char> buf;
    error = lodepng::decode(buf, width, height,
                            (const unsigned char *)contents.data(),
                            contents.size(), LCT_RGB, bpp);
    if (error != 0) {
        fprintf(stderr, "%s: %s", name, lodepng_error_text(error));
        exit(1);
    }

    std::vector<uint16_t> pix;
    if (state.info_png.color.bitdepth == 16) {
        auto bufIter = buf.begin();
        for (unsigned int y = 0; y < height; ++y)
            for (unsigned int x = 0; x < width; ++x, bufIter += 6) {
                assert(bufIter < buf.end());
                // Convert from little endian.
                pix.push_back(((int)bufIter[0] << 8) + (int)bufIter[1]);
                pix.push_back(((int)bufIter[2] << 8) + (int)bufIter[3]);
                pix.push_back(((int)bufIter[4] << 8) + (int)bufIter[5]);
            }
        assert(bufIter == buf.end());
    } else {
        assert(!"todo 8 bit");
    }

    return pix;
}

int main(int argc, char *argv[]) {
    int xres = -1, yres = -1;
    printf("{ ");
    for (++argv; *argv; ++argv) {
        int xr, yr;
        std::vector<uint16_t> png = ReadPNG(*argv, &xr, &yr);
        if (xres == -1) {
            xres = xr;
            yres = yr;
        } else {
            assert(xres == xr);
            assert(yres == yr);
        }
        assert(png.size() == 3 * xres * yres);
        for (int c = 0; c < 3; ++c) {
            int offset = c;
            printf("{ ");
            for (int y = 0; y < yres; ++y) {
                printf("{ ");
                for (int x = 0; x < xres; ++x, offset += 3) {
                    printf("%d, ", png[offset]);
                }
                printf("},\n");
            }
            printf("},\n");
        }
    }
    printf("};\n");
}
 */
